class dynamicRecommendations extends HTMLElement{constructor(){super(),this.productId=this.getAttribute("data-product-id"),this.limit=this.getAttribute("data-product-limit"),this.sectionId=this.getAttribute("data-section-id"),this.recommendationContainer=this.querySelector("[data-product-row]"),this.recommendUrl=`${window.location.origin}/recommendations/products?product_id=${this.productId}&limit=${this.limit}&section_id=${this.sectionId}`,this.loadRecommendations()}loadRecommendations(){fetch(this.recommendUrl).then(t=>t.text()).then(t=>{const e=(new DOMParser).parseFromString(t,"text/html").querySelector("[data-product-row]");e&&(this.recommendationContainer.innerHTML=e.innerHTML),new Yotpo.API(yotpo).refreshWidgets()})}}customElements.define("dynamic-recommendations",dynamicRecommendations);